"""Adds authored intermediate and advanced lessons; preserves beginner IDs."""
import json
from pathlib import Path
p=Path('src/data/foundations.json');lessons=[x for x in json.loads(p.read_text()) if '-i-' not in x['id'] and '-a-' not in x['id']]
for l in lessons:l['level']='Beginner'
def add(lang,slug,title,level,concept,why,example,output,walk,task,solution,target,quiz,options,answer,reason,pitfall,stretch,**extra):
 module=('Working with real data' if level=='Intermediate' else 'Design and reasoning') if lang in ['python','javascript','java'] else ('Accessible structure' if lang=='html' and level=='Intermediate' else 'Robust page patterns' if lang=='html' else 'Layout systems' if level=='Intermediate' else 'Adaptive design')
 starter={'python':'# Build your solution here\n','javascript':'// Build your solution here\n','java':'public class Main {\n    public static void main(String[] args) {\n        // Build your solution here\n    }\n}\n','html':'<!-- Build your page fragment here -->\n','css':'/* Build your stylesheet here */\n'}[lang]
 lessons.append(dict(id=f'{lang}-'+('i-' if level=='Intermediate' else 'a-')+slug,language=lang,title=title,level=level,module=module,minutes=18 if level=='Intermediate' else 25,concept=concept,why=why,example=example,exampleOutput=output,walk=walk,task=task,starter=starter,solution=solution,output=target,quiz=dict(q=quiz,options=options,answer=answer,explanation=reason),hints=[walk[0],walk[-1]],pitfall=pitfall,challenge=stretch,terms=extra.pop('terms',[['Invariant','A fact that stays true while an algorithm runs.'],['Contract','The inputs, outputs and rules a piece of code promises.']]),**extra))
def j(body,methods='',imports=''):
 return imports+'public class Main {\n'+methods+'    public static void main(String[] args) {\n'+'\n'.join('        '+s for s in body.splitlines())+'\n    }\n}'
